import type { Meta, StoryObj } from "@storybook/vue3";
import { h } from "vue";
import { KozmosCounter } from "../../index";

/**
 * Vue's Counter: the stories React's has, with the same names and args,
 * each inside the KozmosThemeProvider the Storybook's decorator gives every
 * story. test/parity draws each of React's in both and holds Vue's render to
 * React's. Generated by `port Counter`.
 */
type Args = Record<string, unknown>;
const SLOTS = ["children"];

const meta: Meta<Args> = {
  title: "Vue/Core/Inputs/Counter",
  component: KozmosCounter,
  parameters: { layout: "centered" },
  // React's node props are Vue's slots: `children` the default slot, the
  // rest slots of their own names, each drawing its arg's text.
  render: (args) => ({
    setup: () => () => {
      const props: Args = {};
      const slots: Record<string, () => string> = {};
      for (const [key, value] of Object.entries(args)) {
        if (!SLOTS.includes(key)) props[key] = value;
        else if (value !== undefined && value !== null)
          slots[key === "children" ? "default" : key] = () => String(value);
      }
      return h(KozmosCounter, props, slots);
    },
  }),
};

export default meta;
type Story = StoryObj<Args>;

export const Default: Story = {
  args: {
    children: "2",
  },
};

export const Brand: Story = {
  args: {
    children: "12",
    tone: "brand",
  },
};

export const Small: Story = {
  args: {
    children: "4",
    size: "sm",
  },
};

export const Destructive: Story = {
  args: {
    children: "3",
    tone: "destructive",
  },
};

/**
 * The six emotions. A counter is always a filled pill, so there is one
 * treatment rather than two. `tone` stays for `inverse`, which is not an
 * emotion at all.
 */
export const Emotions: Story = {
  render: () => ({
    components: { KozmosCounter },
    setup: () => ({
      counts: [
        ["neutral", "8"],
        ["themed", "12"],
        ["success", "3"],
        ["danger", "99"],
        ["informative", "5"],
        ["alert", "41"],
      ],
    }),
    template: `<div class="flex items-center gap-2"><KozmosCounter v-for="[emotion, count] in counts" :key="emotion" :emotion="emotion">{{ count }}</KozmosCounter></div>`,
  }),
};
